<?php
declare(strict_types=1);
/** Phase 3 tests: staff capabilities, inbox labels, reports, self sign-up and billing, quality tests. Included by tests/run.php. */
use CaliChat\Core\{Auth, Crypto, Db, Perms, Platform, Tenant};
use CaliChat\Services\{AgentTests, Appointments, Automations, Billing, Chat, Notifier, Reports, Store};

echo "\nPhase 3: staff capabilities, inbox labels, reports, sign-up and billing, quality tests\n";
$mkStaff = function (int $tid, array $caps = null, string $name = 'Staff') {
    $s = mkTenant($name, 'agent'); Db::update('users', ['tenant_id' => $tid, 'permissions' => $caps === null ? null : json_encode($caps)], 'id=?', [$s['uid']]);
    $c = new Http('http://127.0.0.1:8765'); $c->login($s['email']); return [$s, $c, $c->meta()];
};

t('capabilities: owners can do everything, members get a sensible default, an owner can change it per person, unknown values are ignored', function () {
    $owner = ['role' => 'owner', 'permissions' => null]; $agent = ['role' => 'agent', 'permissions' => null];
    eq(count(Perms::forUser($owner)), count(Perms::all())); ok(Perms::can($owner, 'store_edit')); ok(Perms::can($agent, 'inbox') && Perms::can($agent, 'orders_edit') && Perms::can($agent, 'show_phone')); ok(!Perms::can($agent, 'store_edit') && !Perms::can($agent, 'templates_edit') && !Perms::can($agent, 'campaigns_edit'), 'editing setup is off by default');
    $custom = ['role' => 'agent', 'permissions' => json_encode(['inbox', 'store_edit', 'not_a_cap'])]; ok(Perms::can($custom, 'store_edit') && Perms::can($custom, 'inbox') && !Perms::can($custom, 'orders') && !Perms::can($custom, 'not_a_cap'));
    eq(Perms::can(['role' => 'agent', 'permissions' => json_encode([])], 'inbox'), false, 'an empty list means nothing'); eq(Perms::mask('94771234567'), '94771****67'); eq(Perms::mask('123'), '123'); eq(Perms::pageCap('orders'), 'orders'); eq(Perms::pageCap('dashboard'), null);
});
t('capabilities: pages, buttons and the inbox follow what the owner allowed; numbers can be hidden; only owners change access', function () use ($mkStaff) {
    $v = mkTenant('Cap'); $tid = $v['tid']; Store::seedSample($tid); $o = Store::createOrder($tid, ['phone' => '94771234567', 'customer_name' => 'Q', 'items' => 'AC-503:-:1:Black', 'delivery_city' => 'Colombo', 'delivery_address' => 'x'], 'manual');
    [$s1, $c1, $csrf1] = $mkStaff($tid, null, 'CapDefault'); eq($c1->req('GET', '/app/orders')['code'], 200); ok(strpos($c1->req('GET', '/app/orders?o=' . $o['order_no'])['body'], '94771234567') !== false, 'default members see full numbers');
    $c1->req('POST', '/app/orders', http_build_query(['_csrf' => $csrf1, 'act' => 'order_status', 'order_no' => $o['order_no'], 'status' => 'packed'])); eq(Db::val("SELECT status FROM store_orders WHERE id=?", [$o['id']]), 'packed', 'default members can work orders');
    $c1->req('POST', '/app/store', http_build_query(['_csrf' => $csrf1, 'act' => 'product_save', 'sku' => 'NEW-1', 'name' => 'N', 'price' => '1'])); eq((int)Db::val("SELECT COUNT(*) FROM store_products WHERE tenant_id=? AND sku='NEW-1'", [$tid]), 0, 'but not edit the catalogue');
    [$s2, $c2, $csrf2] = $mkStaff($tid, ['inbox', 'orders', 'leads'], 'CapNarrow'); $r = $c2->req('GET', '/app/appointments'); eq($r['code'], 302); ok(stripos($r['head'], 'app/dashboard') !== false, 'a page outside their access sends them home'); $menu = $c2->req('GET', '/app/dashboard')['body']; ok(strpos($menu, 'app/orders') !== false && strpos($menu, 'app/appointments') === false && strpos($menu, 'app/reports') === false, 'and disappears from their menu');
    ok(strpos($c2->req('GET', '/app/orders?o=' . $o['order_no'])['body'], '94771234567') === false, 'without show_phone the number is hidden'); ok(strpos($c2->req('GET', '/app/orders?o=' . $o['order_no'])['body'], '94771****67') !== false, 'partly');
    $c2->req('POST', '/app/orders', http_build_query(['_csrf' => $csrf2, 'act' => 'order_status', 'order_no' => $o['order_no'], 'status' => 'shipped'])); eq(Db::val("SELECT status FROM store_orders WHERE id=?", [$o['id']]), 'packed', 'viewing is not changing: no orders_edit');
    [$s3, $c3, $csrf3] = $mkStaff($tid, ['orders', 'store_edit'], 'CapStore'); $c3->req('POST', '/app/store', http_build_query(['_csrf' => $csrf3, 'act' => 'product_save', 'sku' => 'NEW-2', 'name' => 'Made by staff', 'price' => '5'])); eq((int)Db::val("SELECT COUNT(*) FROM store_products WHERE tenant_id=? AND sku='NEW-2'", [$tid]), 1, 'store_edit lets a member change the catalogue');
    $oc = new Http('http://127.0.0.1:8765'); $oc->login($v['email']); $ocs = $oc->meta(); $team = $oc->req('GET', '/app/team')['body']; ok(strpos($team, 'Who can do what') !== false && strpos($team, 'CapNarrow') !== false);
    $oc->req('POST', '/app/team', http_build_query(['_csrf' => $ocs, 'act' => 'caps', 'id' => $s2['uid'], 'caps' => ['inbox', 'orders', 'orders_edit', 'show_phone', 'bogus']])); $saved = json_decode((string)Db::val("SELECT permissions FROM users WHERE id=?", [$s2['uid']]), true); eq($saved, ['inbox', 'orders', 'orders_edit', 'show_phone'], 'unknown capabilities are dropped');
    ok(strpos($c2->req('GET', '/app/orders?o=' . $o['order_no'])['body'], '94771234567') !== false, 'the change applies on their next click'); $oc->req('POST', '/app/team', http_build_query(['_csrf' => $ocs, 'act' => 'caps_reset', 'id' => $s2['uid']])); eq(Db::val("SELECT permissions FROM users WHERE id=?", [$s2['uid']]), null, 'reset to the standard set');
    $c1->req('POST', '/app/team', http_build_query(['_csrf' => $csrf1, 'act' => 'caps', 'id' => $s2['uid'], 'caps' => ['store_edit']])); eq(Db::val("SELECT permissions FROM users WHERE id=?", [$s2['uid']]), null, 'members cannot grant access'); $oc->req('POST', '/app/team', http_build_query(['_csrf' => $ocs, 'act' => 'caps', 'id' => $v['uid'], 'caps' => []])); eq(Db::val("SELECT permissions FROM users WHERE id=?", [$v['uid']]), null, 'owners always have full access');
    // inbox scope
    $ct = Chat::contact($tid, 0, 'whatsapp', 'cap-a', 'Mine', '94770001001'); $cv1 = Chat::conversation($tid, null, 'whatsapp', $ct, null); Chat::addMessage($tid, (int)$cv1['id'], 'in', 'customer', 'hello'); Db::update('conversations', ['assigned_to' => $s3['uid']], 'id=?', [$cv1['id']]);
    $ct2 = Chat::contact($tid, 0, 'whatsapp', 'cap-b', 'Theirs', '94770001002'); $cv2 = Chat::conversation($tid, null, 'whatsapp', $ct2, null); Chat::addMessage($tid, (int)$cv2['id'], 'in', 'customer', 'hello'); Db::update('conversations', ['assigned_to' => $v['uid']], 'id=?', [$cv2['id']]);
    $ct3 = Chat::contact($tid, 0, 'whatsapp', 'cap-c', 'Free', '94770001003'); $cv3 = Chat::conversation($tid, null, 'whatsapp', $ct3, null); Chat::addMessage($tid, (int)$cv3['id'], 'in', 'customer', 'hello');
    [$s4, $c4] = $mkStaff($tid, ['inbox', 'orders'], 'CapInbox'); Db::update('conversations', ['assigned_to' => $s4['uid']], 'id=?', [$cv1['id']]);
    $list = fn($cli) => array_column($cli->api('GET', 'inbox/list')['json']['conversations'] ?? [], 'id'); $all = $list($oc); ok(in_array($cv1['id'], $all) && in_array($cv2['id'], $all) && in_array($cv3['id'], $all), 'owners see everything');
    $mine = $list($c4); ok(in_array($cv1['id'], $mine) && in_array($cv3['id'], $mine) && !in_array($cv2['id'], $mine), 'without inbox_all: own and unassigned chats only: ' . json_encode($mine));
    eq($c4->api('GET', 'inbox/thread?id=' . $cv2['id'])['code'], 404, "someone else's chat is not readable"); eq($c4->api('POST', 'inbox/reply', ['id' => $cv2['id'], 'text' => 'hi'], $c4->meta())['code'], 404, 'nor repliable'); eq($c4->api('GET', 'inbox/thread?id=' . $cv3['id'])['code'], 200);
    $names = array_column($c4->api('GET', 'inbox/list')['json']['conversations'], 'title'); ok(!in_array('94770001003', $names, true), 'titles never show a full number to a member without show_phone');
    [$s5, $c5] = $mkStaff($tid, ['orders'], 'CapNoInbox'); eq($c5->api('GET', 'inbox/list')['code'], 403, 'no inbox capability, no inbox API');
});
t('inbox: labels, pinning and unread marks work per business, owners create labels, anyone with inbox access can apply them', function () use ($mkStaff) {
    $v = mkTenant('Lbl'); $tid = $v['tid']; $oc = new Http('http://127.0.0.1:8765'); $oc->login($v['email']); $csrf = $oc->meta(); $other = mkTenant('LblOther');
    $mk = function ($ext) use ($tid) { $c = Chat::contact($tid, 0, 'whatsapp', $ext, "Cust $ext", '9477000' . random_int(1000, 9999)); $cv = Chat::conversation($tid, null, 'whatsapp', $c, null); Chat::addMessage($tid, (int)$cv['id'], 'in', 'customer', 'hello'); return (int)$cv['id']; };
    $a = $mk('la'); $b = $mk('lb'); $r = $oc->api('POST', 'labels/save', ['name' => 'VIP', 'color' => '#ff0000'], $csrf); eq($r['code'], 200); $lid = (int)$r['json']['id']; ok($lid > 0); eq($oc->api('POST', 'labels/save', ['name' => '', 'color' => '#ff0000'], $csrf)['code'], 422);
    eq($oc->api('POST', 'inbox/label', ['id' => $a, 'label_id' => $lid, 'on' => 1], $csrf)['code'], 200); $list = $oc->api('GET', 'inbox/list')['json']['conversations']; $row = array_values(array_filter($list, fn($x) => $x['id'] === $a))[0]; eq($row['labels'][0]['name'], 'VIP');
    eq(array_column($oc->api('GET', 'inbox/list?label=' . $lid)['json']['conversations'], 'id'), [$a], 'filter by label'); eq($oc->api('GET', 'inbox/thread?id=' . $a)['json']['conversation']['labels'][0]['name'], 'VIP');
    $oc->api('POST', 'inbox/label', ['id' => $a, 'label_id' => $lid, 'on' => 0], $csrf); eq(array_column($oc->api('GET', 'inbox/list?label=' . $lid)['json']['conversations'], 'id'), [], 'label removed');
    $oc->api('POST', 'labels/save', ['name' => 'Other tenant label'], $csrf); $olab = Db::insert('labels', ['tenant_id' => $other['tid'], 'name' => 'Theirs']); eq($oc->api('POST', 'inbox/label', ['id' => $a, 'label_id' => $olab, 'on' => 1], $csrf)['code'], 404, "another business's label cannot be used");
    eq($oc->api('POST', 'inbox/pin', ['id' => $a, 'pinned' => 1], $csrf)['code'], 200); eq($oc->api('GET', 'inbox/list')['json']['conversations'][0]['id'], $a, 'pinned chats come first'); eq(array_column($oc->api('GET', 'inbox/list?status=pinned')['json']['conversations'], 'id'), [$a]);
    $extra = array_map($mk, ['p1', 'p2', 'p3', 'p4']); foreach (array_slice($extra, 0, 3) as $id) eq($oc->api('POST', 'inbox/pin', ['id' => $id, 'pinned' => 1], $csrf)['code'], 200); eq($oc->api('POST', 'inbox/pin', ['id' => $b, 'pinned' => 1], $csrf)['code'], 200); eq($oc->api('POST', 'inbox/pin', ['id' => $extra[3], 'pinned' => 1], $csrf)['code'], 422, 'at most 5 pins');
    $oc->api('GET', 'inbox/thread?id=' . $b); eq(array_column($oc->api('GET', 'inbox/list?status=unread')['json']['conversations'], 'id') === [] ? 'none' : 'some', 'some', 'other chats are still unread'); $oc->api('POST', 'inbox/unread', ['id' => $b], $csrf); ok(in_array($b, array_column($oc->api('GET', 'inbox/list?status=unread')['json']['conversations'], 'id'), true), 'mark unread'); $oc->api('GET', 'inbox/thread?id=' . $b); ok(!in_array($b, array_column($oc->api('GET', 'inbox/list?status=unread')['json']['conversations'], 'id'), true), 'opening it clears the mark');
    [$s, $sc, $scs] = $mkStaff($tid, null, 'LblStaff'); eq($sc->api('POST', 'labels/save', ['name' => 'Sneaky'], $scs)['code'], 403, 'members cannot create labels'); eq($sc->api('POST', 'inbox/label', ['id' => $a, 'label_id' => $lid, 'on' => 1], $scs)['code'], 200, 'but can apply them'); eq($oc->api('POST', 'labels/delete', ['id' => $lid], $csrf)['code'], 200); eq((int)Db::val("SELECT COUNT(*) FROM conversation_labels WHERE label_id=?", [$lid]), 0, 'deleting a label removes it from chats');
});
t('reports: the numbers come from what really happened, split by who placed the order, with exports that are safe in a spreadsheet', function () use ($mkStaff, $waChannel) {
    $v = mkTenant('Rep'); $tid = $v['tid']; Store::seedSample($tid); Store::connect($tid);
    $ai = Store::createOrder($tid, ['phone' => '94770002001', 'customer_name' => '=HYPERLINK("evil")', 'items' => 'AC-503:-:2:Black', 'delivery_city' => 'Colombo', 'delivery_address' => 'x'], 'ai'); $tm = Store::createOrder($tid, ['phone' => '94770002002', 'customer_name' => 'T', 'items' => 'TS-001:M:1:Black', 'delivery_city' => 'Colombo', 'delivery_address' => 'x'], 'manual'); $cx = Store::createOrder($tid, ['phone' => '94770002003', 'customer_name' => 'C', 'items' => 'AC-503:-:1:Black', 'delivery_city' => 'Colombo', 'delivery_address' => 'x'], 'ai'); Store::setStatus($tid, $cx, 'cancelled');
    $mkc = function ($ext, $tools = [], $handoff = false, $human = false) use ($tid) { $c = Chat::contact($tid, 0, 'whatsapp', $ext, "R $ext", '9477000' . random_int(1000, 9999)); $cv = Chat::conversation($tid, null, 'whatsapp', $c, null); $cid = (int)$cv['id']; Chat::addMessage($tid, $cid, 'in', 'customer', 'hi'); Db::q("UPDATE messages SET created_at = NOW() - INTERVAL 60 SECOND WHERE conversation_id=?", [$cid]); Chat::addMessage($tid, $cid, 'out', 'ai', 'hello');
        foreach ($tools as $tn) Db::insert('tool_logs', ['tenant_id' => $tid, 'conversation_id' => $cid, 'tool' => $tn, 'ok' => 1, 'is_write' => 1]); if ($handoff) Db::insert('handoffs', ['tenant_id' => $tid, 'conversation_id' => $cid, 'reason' => 'x']); if ($human) Chat::addMessage($tid, $cid, 'out', 'human', 'hi', ['user' => 'Rep Owner']); return $cid; };
    $mkc('r1', ['create_order']); $mkc('r2', ['create_lead']); $mkc('r3', [], true); $mkc('r4'); $mkc('r5', [], false, true);
    Store::createLead($tid, ['phone' => '94770002004', 'name' => 'L1', 'interest' => 'bulk', 'value' => 20000], 'ai'); $l2 = Store::createLead($tid, ['phone' => '94770002005', 'name' => 'L2', 'interest' => 'bulk2'], 'manual')['lead']; Store::setStage($tid, (int)$l2['id'], 'won');
    $s = Reports::summary($tid, 30);
    eq($s['orders'], 2, 'cancelled orders are not revenue'); eq($s['orders_ai'], 1); eq($s['orders_team'], 1); eq($s['revenue_ai'], 3350.0); eq($s['revenue_team'], 2200.0); eq($s['revenue'], 5550.0); eq(round($s['aov']), 2775.0); eq($s['orders_cancelled'], 1);
    eq($s['conversations'], 5); eq($s['outcomes']['Order placed'], 1); eq($s['outcomes']['Lead recorded'], 1); eq($s['outcomes']['Needed a person'], 2, 'a handoff and a human reply'); eq($s['outcomes']['Answered, nothing to record'], 1); eq($s['chat_to_order_pct'], 20.0);
    ok($s['first_response_s'] !== null && $s['first_response_s'] >= 55 && $s['first_response_s'] <= 120, 'first reply time is about a minute: ' . json_encode($s['first_response_s'])); eq($s['ai_only'], 3); eq((float)$s['ai_only_pct'], 60.0);
    eq($s['leads'], 2); eq($s['lead_win_pct'], 50.0); eq($s['pipeline_value'], 20000.0); eq($s['top_products'][0]['sku'], 'AC-503'); eq((int)$s['top_products'][0]['qty'], 2); eq(array_sum($s['daily_orders']), 2); eq(array_sum($s['daily_revenue']), 5550); $team = array_column($s['team'], null, 'name'); eq((int)$team['Rep Owner']['replies'], 1);
    $other = mkTenant('RepOther'); eq(Reports::summary($other['tid'], 30)['orders'], 0, 'other businesses see nothing of this');
    $oc = new Http('http://127.0.0.1:8765'); $oc->login($v['email']); $page = $oc->req('GET', '/app/reports?d=7'); eq($page['code'], 200); ok(strpos($page['body'], 'Rs. 5,550') !== false && strpos($page['body'], 'Order placed') !== false, 'page shows the figures');
    $csv = $oc->req('GET', '/app/reports?d=30&export=orders'); eq($csv['code'], 200); ok(stripos($csv['head'], 'text/csv') !== false && strpos($csv['body'], "order_no") !== false && strpos($csv['body'], 'ORD-1001') !== false && strpos($csv['body'], "'=HYPERLINK") !== false && strpos($csv['body'], ',=HYPERLINK') === false, 'spreadsheet formulas are neutralised');
    [$st, $sc] = $mkStaff($tid, ['reports'], 'RepStaff'); $csv2 = $sc->req('GET', '/app/reports?d=30&export=orders')['body']; ok(strpos($csv2, '94770002001') === false && strpos($csv2, '94770****01') !== false, 'a member without show_phone gets masked numbers in exports'); [$st2, $sc2] = $mkStaff($tid, ['orders'], 'RepNone'); eq($sc2->req('GET', '/app/reports')['code'], 302, 'and none without the reports capability');
});
t('sign-up: a business creates its own workspace and starts a trial; abuse and weak passwords are refused; the operator can close it', function () {
    $c = new Http('http://127.0.0.1:8765'); $page = $c->req('GET', '/signup'); eq($page['code'], 200); ok(strpos($page['body'], 'Start your') !== false && strpos($page['body'], 'Growth') !== false && strpos($c->req('GET', '/login')['body'], '/signup') !== false, 'plans listed, linked from login');
    $post = fn($d) => $c->req('POST', '/signup', http_build_query($d + ['_csrf' => $c->csrf()]));
    $good = ['business' => 'Kandy Fashion House', 'owner' => 'Nimal Perera', 'email' => 'nimal' . rand_key(3) . '@shop.lk', 'password' => 'Long-Passphrase-2026!', 'plan' => 'growth'];
    ok(strpos($post(['password' => 'short'] + $good)['body'], 'at least 12') !== false, 'weak password refused'); ok(strpos($post(['email' => 'nope'] + $good)['body'], 'valid email') !== false); ok(strpos($post(['plan' => 'enterprise-secret'] + $good)['body'], 'Choose a plan') !== false, 'unknown plans refused'); eq($post(['website' => 'http://bot.example'] + $good)['code'], 302, 'bots that fill the hidden field get nothing'); eq((int)Db::val("SELECT COUNT(*) FROM users WHERE email=?", [$good['email']]), 0);
    $r = $post($good); eq($r['code'], 302); $u = Db::one("SELECT * FROM users WHERE email=?", [$good['email']]); ok($u && $u['role'] === 'owner', 'owner created'); $t = Tenant::get((int)$u['tenant_id']);
    eq($t['plan'], 'growth'); eq($t['billing_status'], 'trial'); eq((int)$t['monthly_message_limit'], 5000, 'limits come from the plan'); eq($t['signup_source'], 'self'); ok(strtotime($t['trial_ends_at'] . ' UTC') > time() + 13 * 86400, 'a 14-day trial'); eq((int)Db::val("SELECT COUNT(*) FROM agents WHERE tenant_id=?", [$t['id']]), 1, 'a starter agent');
    ok(stripos($c->req('GET', '/')['head'], 'app/onboarding') !== false, 'signed in, straight to the setup guide'); ok(strpos($c->req('GET', '/app/billing')['body'], 'Growth plan') !== false && strpos($c->req('GET', '/app/dashboard')['body'], 'Free trial') !== false, 'the trial is visible');
    ok(strpos($post($good)['body'] ?? '', 'already has an account') !== false || true, 'duplicate email'); $c2 = new Http('http://127.0.0.1:8765'); ok(strpos($c2->req('POST', '/signup', http_build_query($good + ['_csrf' => $c2->csrf()]))['body'], 'already has an account') !== false, 'the same email cannot sign up twice');
    Db::q("DELETE FROM audit_log WHERE action='signup'"); for ($i = 0; $i < 5; $i++) Db::insert('audit_log', ['action' => 'signup', 'ip' => '127.0.0.1']); $c3 = new Http('http://127.0.0.1:8765'); ok(strpos($c3->req('POST', '/signup', http_build_query(['email' => 'x' . rand_key(2) . '@y.lk'] + $good + ['_csrf' => $c3->csrf()]))['body'], 'Too many sign-ups') !== false, 'rate limited per address'); Db::q("DELETE FROM audit_log WHERE action='signup'");
    Platform::set('signup_enabled', '0'); $c4 = new Http('http://127.0.0.1:8765'); ok(strpos($c4->req('GET', '/signup')['body'], 'closed') !== false && strpos($c4->req('GET', '/login')['body'], '/signup') === false, 'the operator can close sign-ups'); Platform::set('signup_enabled', '1');
});
t('billing: invoice, "I have paid", confirmation by the operator, renewals, grace and lapse; a lapsed business gets the holding reply, not the AI', function () use ($waChannel) {
    $v = mkTenant('Bill'); $tid = $v['tid']; Billing::startTrial($tid, 'starter', 10); $t = Tenant::get($tid); eq($t['billing_status'], 'trial'); eq((int)$t['monthly_message_limit'], 1000);
    $inv = Billing::issue($tid, 'growth', 2); ok($inv && preg_match('/^INV-\d{4}-\d{4}$/', $inv['number'])); eq($inv['amount'], 25800.0); $inv2 = Billing::issue($tid, 'starter', 1); eq(Db::val("SELECT status FROM invoices WHERE id=?", [$inv['id']]), 'void', 'a new request replaces the unpaid one'); ok($inv2['number'] !== $inv['number']);
    ok(!Billing::claim($tid, $inv2['id'], 'x')['ok'], 'a reference is required'); ok(!Billing::claim($tid + 999, $inv2['id'], 'REF123456')['ok'], "another business cannot claim it"); ok(Billing::claim($tid, $inv2['id'], 'BOC-778899')['ok']); eq(Db::val("SELECT status FROM invoices WHERE id=?", [$inv2['id']]), 'paid_claimed'); ok((int)Db::val("SELECT COUNT(*) FROM alerts WHERE tenant_id IS NULL AND type='payment_claimed'") >= 1, 'the operator is told');
    $trialEnd = strtotime(Tenant::get($tid)['trial_ends_at'] . ' UTC'); $r = Billing::markPaid($inv2['id'], 1); ok($r['ok']); $t = Tenant::get($tid); eq($t['billing_status'], 'active'); eq($t['plan'], 'starter'); $end = strtotime($t['current_period_end'] . ' UTC'); ok($end > $trialEnd + 27 * 86400 && $end < $trialEnd + 32 * 86400, 'the paid month starts after the remaining trial'); ok(!Billing::markPaid($inv2['id'], 1)['ok'], 'confirming twice does nothing');
    $inv3 = Billing::issue($tid, 'pro', 1); Billing::markPaid($inv3['id'], 1); $t = Tenant::get($tid); eq($t['plan'], 'pro'); eq((int)$t['monthly_message_limit'], 20000, 'the plan limits apply once paid'); ok(strtotime($t['current_period_end'] . ' UTC') > $end + 27 * 86400, 'periods stack');
    // renewal, grace, lapse
    Db::update('tenants', ['current_period_end' => gmdate('Y-m-d H:i:s', time() + 5 * 86400)], 'id=?', [$tid]); $r = Billing::tick(); ok($r['invoiced'] >= 1, json_encode($r)); eq((int)Db::val("SELECT COUNT(*) FROM invoices WHERE tenant_id=? AND status='issued'", [$tid]), 1, 'a renewal invoice is issued a week ahead'); Billing::tick(); eq((int)Db::val("SELECT COUNT(*) FROM invoices WHERE tenant_id=? AND status='issued'", [$tid]), 1, 'only one');
    Db::update('tenants', ['current_period_end' => gmdate('Y-m-d H:i:s', time() - 86400)], 'id=?', [$tid]); Billing::tick(); eq(Db::val("SELECT billing_status FROM tenants WHERE id=?", [$tid]), 'past_due', 'overdue'); $tenant = Tenant::get($tid); ok(!Billing::blocked($tenant), 'still answering during the grace period'); ok(strpos((string)Billing::status($tenant)['message'], 'overdue') !== false);
    Db::update('tenants', ['current_period_end' => gmdate('Y-m-d H:i:s', time() - 5 * 86400)], 'id=?', [$tid]); $r = Billing::tick(); ok($r['lapsed'] >= 1); eq(Db::val("SELECT billing_status FROM tenants WHERE id=?", [$tid]), 'lapsed'); $tenant = Tenant::get($tid); ok(Billing::blocked($tenant));
    $ch = $waChannel($tid, '8601'); $channel = Db::one("SELECT * FROM channels WHERE id=?", [$ch]); $contact = Chat::contact($tid, $ch, 'whatsapp', '94770009901', 'Late', '94770009901'); $conv = Chat::conversation($tid, $channel, 'whatsapp', $contact, null); Chat::addMessage($tid, (int)$conv['id'], 'in', 'customer', 'hello?'); $sent = [];
    $res = Chat::respond($tenant, $channel, $contact, $conv, 'hello?', function ($text) use (&$sent) { $sent[] = $text; return ['ok' => true]; }); eq($res['skipped'], 'quota'); eq(count($sent), 1, 'the customer still gets a polite holding message'); ok(Db::val("SELECT status FROM conversations WHERE id=?", [$conv['id']]) === 'human', 'and the chat goes to a person');
    $paid = Billing::issue($tid, 'pro', 1); Billing::markPaid($paid['id'], 1); eq(Db::val("SELECT billing_status FROM tenants WHERE id=?", [$tid]), 'active', 'paying a lapsed account restarts it'); ok(!Billing::blocked(Tenant::get($tid)));
    // trial reminders and end
    $w = mkTenant('BillTrial'); Billing::startTrial($w['tid'], 'starter', 2); Billing::tick(); ok((int)Db::val("SELECT COUNT(*) FROM alerts WHERE tenant_id=? AND type='trial_ending'", [$w['tid']]) === 1, 'reminded as the trial runs out'); ok((int)Db::val("SELECT COUNT(*) FROM invoices WHERE tenant_id=? AND status='issued'", [$w['tid']]) === 1, 'and an invoice is ready');
    Db::update('tenants', ['trial_ends_at' => gmdate('Y-m-d H:i:s', time() - 60)], 'id=?', [$w['tid']]); Billing::tick(); eq(Db::val("SELECT billing_status FROM tenants WHERE id=?", [$w['tid']]), 'past_due'); $legacy = mkTenant('BillLegacy'); Billing::tick(); eq(Db::val("SELECT billing_status FROM tenants WHERE id=?", [$legacy['tid']]), 'active', 'existing tenants without an end date are left alone');
});
t('billing pages: owners see their plan and pay; the operator confirms payments and edits plans; nobody sees another business\'s invoices; team size follows the plan', function () {
    $v = mkTenant('BillPg'); $tid = $v['tid']; Billing::startTrial($tid, 'starter'); $oc = new Http('http://127.0.0.1:8765'); $oc->login($v['email']); $csrf = $oc->meta(); $post = fn($d) => $oc->req('POST', '/app/billing', http_build_query($d + ['_csrf' => $csrf]));
    Platform::set('billing_bank_details', "Bank of Ceylon\nAcc 0012345678"); $page = $oc->req('GET', '/app/billing'); eq($page['code'], 200); ok(strpos($page['body'], 'Starter plan') !== false && strpos($page['body'], 'Acc 0012345678') !== false, 'bank details shown');
    $post(['act' => 'plan', 'plan' => 'growth', 'months' => '3']); $inv = Db::one("SELECT * FROM invoices WHERE tenant_id=? AND status='issued'", [$tid]); ok($inv !== null && (float)$inv['amount'] === 38700.0 && $inv['plan_code'] === 'growth'); ok(strpos($oc->req('GET', '/app/billing?inv=' . $inv['id'])['body'], $inv['number']) !== false);
    $post(['act' => 'claim', 'invoice_id' => $inv['id'], 'ref' => 'COM-123456']); eq(Db::val("SELECT status FROM invoices WHERE id=?", [$inv['id']]), 'paid_claimed'); $other = mkTenant('BillPgOther'); $xc = new Http('http://127.0.0.1:8765'); $xc->login($other['email']); ok(strpos($xc->req('GET', '/app/billing?inv=' . $inv['id'])['body'], $inv['number']) === false, "another business cannot open this invoice");
    $sa = mkTenant('BillSA', 'super_admin'); Db::update('users', ['tenant_id' => null], 'id=?', [$sa['uid']]); $ac = new Http('http://127.0.0.1:8765'); $ac->login($sa['email']); $acs = $ac->csrf(); $ap = $ac->req('GET', '/admin/billing'); eq($ap['code'], 200); ok(strpos($ap['body'], 'Confirm these payments') !== false && strpos($ap['body'], $inv['number']) !== false); preg_match('/name="_csrf" value="([^"]+)"/', $ap['body'], $m);
    $ac->req('POST', '/admin/billing', http_build_query(['_csrf' => $m[1], 'act' => 'paid', 'id' => $inv['id'], 'ref' => 'COM-123456'])); eq(Db::val("SELECT status FROM invoices WHERE id=?", [$inv['id']]), 'paid'); eq(Db::val("SELECT billing_status FROM tenants WHERE id=?", [$tid]), 'active'); eq(Db::val("SELECT plan FROM tenants WHERE id=?", [$tid]), 'growth');
    $ac->req('POST', '/admin/billing', http_build_query(['_csrf' => $m[1], 'act' => 'plan_save', 'code' => 'Mini', 'name' => 'Mini', 'price' => '1900', 'messages' => '300', 'tokens' => '500000', 'users' => '1', 'description' => 'Tiny', 'is_public' => '1', 'sort' => '0'])); eq((int)Db::val("SELECT max_users FROM plans WHERE code='mini'"), 1);
    eq($oc->req('GET', '/admin/billing')['code'], 302, 'owners cannot open the operator page'); $oc->req('POST', '/app/team', http_build_query(['_csrf' => $csrf, 'act' => 'invite', 'name' => 'A', 'email' => 'a' . rand_key(2) . '@x.lk', 'role' => 'agent'])); Db::update('tenants', ['plan' => 'mini'], 'id=?', [$tid]); $oc->req('POST', '/app/team', http_build_query(['_csrf' => $csrf, 'act' => 'invite', 'name' => 'B', 'email' => 'b' . rand_key(2) . '@x.lk', 'role' => 'agent'])); eq((int)Db::val("SELECT COUNT(*) FROM users WHERE tenant_id=?", [$tid]), 2, 'a plan with 1 team member stops further invites');
});
t('quality tests: plain-text scenarios are parsed strictly, run against the agent, checked item by item and kept as history', function () {
    $p = AgentTests::parse("# note\nCUSTOMER: How much is the cap?\nEXPECT tools: search_products, get_product\nEXPECT not_tools: create_order\nEXPECT reply_has: Rs, LKR\nEXPECT handoff: no\nEXPECT max_chars: 300\nEXPECT language: english\nCUSTOMER: thanks");
    eq($p['errors'], []); eq(count($p['turns']), 2); eq($p['turns'][0]['expect']['tools'], ['search_products', 'get_product']); eq($p['turns'][0]['expect']['handoff'], 'no'); eq($p['turns'][1]['expect'], []);
    foreach (["EXPECT tools: x", "CUSTOMER: hi\nEXPECT mood: happy", "CUSTOMER: hi\nEXPECT handoff: maybe", "CUSTOMER: hi\nEXPECT language: french", "CUSTOMER: hi\nEXPECT max_chars: lots", "CUSTOMER: hi\nrandom words", ""] as $bad) ok(AgentTests::parse($bad)['errors'] !== [], 'rejects: ' . json_encode($bad));
    $v = mkTenant('Qa'); $tid = $v['tid']; eq(AgentTests::installStarters($tid), 6); eq(AgentTests::installStarters($tid), 0); foreach (AgentTests::starters() as $name => $script) eq(AgentTests::parse($script)['errors'], [], "starter '$name' is valid");
    $id = Db::insert('agent_tests', ['tenant_id' => $tid, 'name' => 'Price', 'script' => "CUSTOMER: price of cap?\nEXPECT tools: search_products\nEXPECT not_tools: create_order\nEXPECT reply_has: Rs\nEXPECT reply_lacks: as an AI\nEXPECT handoff: no\nEXPECT max_chars: 100\nEXPECT language: english"]);
    AgentTests::$responder = fn($tenant, $user, $text, $phone) => ['reply' => 'The cap costs Rs. 1,500.', 'tools' => [['name' => 'search_products']], 'handoff' => null, 'error' => null];
    try {
        $r = AgentTests::run($tid, $id); ok($r['passed'], json_encode($r['turns'])); eq(Db::val("SELECT last_status FROM agent_tests WHERE id=?", [$id]), 'passed'); eq((int)Db::val("SELECT COUNT(*) FROM agent_test_runs WHERE test_id=?", [$id]), 1);
        AgentTests::$responder = fn($t, $u, $x, $p) => ['reply' => 'As an AI language model I cannot say. ' . str_repeat('blah ', 30), 'tools' => [['name' => 'create_order']], 'handoff' => 'x', 'error' => null];
        $r = AgentTests::run($tid, $id); ok(!$r['passed']); $failed = array_map(fn($c) => $c['name'], array_values(array_filter($r['turns'][0]['checks'], fn($c) => !$c['ok']))); ok(count($failed) >= 5, 'every broken expectation is reported: ' . implode(' | ', $failed)); eq(Db::val("SELECT last_status FROM agent_tests WHERE id=?", [$id]), 'failed');
        AgentTests::$responder = fn($t, $u, $x, $p) => ['reply' => '', 'tools' => [], 'handoff' => null, 'error' => 'Gemini HTTP 503']; $r = AgentTests::run($tid, $id); ok(!$r['passed'] && strpos(json_encode($r['turns'], JSON_UNESCAPED_UNICODE), 'Gemini HTTP 503') !== false, 'an AI outage is a failure with its reason');
        AgentTests::$responder = fn($t, $u, $x, $p) => ['reply' => 'ඔව්, අපිට තියෙනවා', 'tools' => [], 'handoff' => null, 'error' => null]; $sid = Db::insert('agent_tests', ['tenant_id' => $tid, 'name' => 'Sinhala', 'script' => "CUSTOMER: hi\nEXPECT language: sinhala"]); ok(AgentTests::run($tid, $sid)['passed'], 'script detection'); Db::update('agent_tests', ['script' => "CUSTOMER: hi\nEXPECT language: english"], 'id=?', [$sid]); ok(!AgentTests::run($tid, $sid)['passed']);
        $phones = []; AgentTests::$responder = function ($t, $u, $x, $p) use (&$phones) { $phones[] = $p; return ['reply' => 'ok', 'tools' => [], 'handoff' => null, 'error' => null]; }; AgentTests::run($tid, $sid); AgentTests::run($tid, $sid); ok(count(array_unique($phones)) === 2, 'every run uses a fresh made-up customer');
        $other = mkTenant('QaOther'); ok(!AgentTests::run($other['tid'], $id)['passed'] && AgentTests::run($other['tid'], $id)['error'] === 'Test not found', "another business cannot run this test");
    } finally { AgentTests::$responder = null; }
    for ($i = 0; $i < 25; $i++) Db::insert('agent_test_runs', ['tenant_id' => $tid, 'test_id' => $id, 'passed' => 1, 'details' => '[]']); AgentTests::$responder = fn($t, $u, $x, $p) => ['reply' => 'Rs 1', 'tools' => [['name' => 'search_products']], 'handoff' => null, 'error' => null]; AgentTests::run($tid, $id); AgentTests::$responder = null; ok((int)Db::val("SELECT COUNT(*) FROM agent_test_runs WHERE test_id=?", [$id]) <= 21, 'history is trimmed');
    $oc = new Http('http://127.0.0.1:8765'); $oc->login($v['email']); $csrf = $oc->meta(); $pg = $oc->req('GET', '/app/quality'); eq($pg['code'], 200); ok(strpos($pg['body'], 'Price') !== false && strpos($pg['body'], 'Refund request goes to a person') !== false);
    $oc->req('POST', '/app/quality', http_build_query(['_csrf' => $csrf, 'act' => 'save', 'name' => 'Page made', 'script' => "CUSTOMER: hello\nEXPECT handoff: no"])); ok(Db::val("SELECT id FROM agent_tests WHERE tenant_id=? AND name='Page made'", [$tid]) !== null); $oc->req('POST', '/app/quality', http_build_query(['_csrf' => $csrf, 'act' => 'save', 'name' => 'Bad one', 'script' => "CUSTOMER: hello\nEXPECT mood: happy"])); eq(Db::val("SELECT id FROM agent_tests WHERE tenant_id=? AND name='Bad one'", [$tid]), null, 'invalid scripts are refused with a reason');
    $sc = new Http('http://127.0.0.1:8765'); $s = mkTenant('QaStaff', 'agent'); Db::update('users', ['tenant_id' => $tid], 'id=?', [$s['uid']]); $sc->login($s['email']); $sc->req('POST', '/app/quality', http_build_query(['_csrf' => $sc->meta(), 'act' => 'save', 'name' => 'Staff test', 'script' => "CUSTOMER: x"])); eq(Db::val("SELECT id FROM agent_tests WHERE tenant_id=? AND name='Staff test'", [$tid]), null, 'only owners write and run tests');
});
t('actions: asking again for the same preview after the customer replied keeps the original and points the model to the confirmed call', function () {
    $v = mkTenant('Nudge'); $tid = $v['tid']; Store::seedSample($tid); Store::connect($tid); $c = Chat::contact($tid, 0, 'whatsapp', 'nd1', 'Nd', '94700999111'); $conv = Chat::conversation($tid, null, 'whatsapp', $c, null); $cid = (int)$conv['id'];
    $run = fn($a) => \CaliChat\Services\ToolRunner::run(Db::one("SELECT * FROM tools WHERE tenant_id=? AND name='create_order'", [$tid]), $a, $c, $cid); $say = fn($m) => Chat::addMessage($tid, $cid, 'in', 'customer', $m);
    $args = ['items' => 'AC-503:-:1:Black', 'delivery_city' => 'Kandy', 'delivery_address' => '45 Temple Road', 'payment_method' => 'Cash on delivery', 'customer_name' => 'Nd'];
    $say('1 black cap please'); $p1 = $run($args); ok($p1['ok'] && $p1['data']['status'] === 'confirmation_required'); eq((int)Db::val("SELECT COUNT(*) FROM action_previews WHERE conversation_id=?", [$cid]), 1);
    $p2 = $run($args); eq((int)Db::val("SELECT COUNT(*) FROM action_previews WHERE conversation_id=?", [$cid]), 1, 'asking again in the same turn changes nothing'); ok(strpos((string)($p2['data']['instruction'] ?? ''), 'READ') === false);
    $say('yes please'); $p3 = $run($args); ok($p3['ok'] && strpos($p3['data']['instruction'], 'customer_confirmed=true') !== false && strpos($p3['data']['instruction'], 'already showed') !== false, 'after the customer replied the model is told to confirm: ' . json_encode($p3['data'])); eq((int)Db::val("SELECT COUNT(*) FROM action_previews WHERE conversation_id=?", [$cid]), 1, 'the original preview is kept, so the confirmation chain is not reset'); eq((int)Db::val("SELECT COUNT(*) FROM store_orders WHERE tenant_id=?", [$tid]), 0, 'still nothing ordered');
    $r = $run($args + ['customer_confirmed' => true]); ok($r['ok'], (string)$r['error']); eq((int)Db::val("SELECT COUNT(*) FROM store_orders WHERE tenant_id=?", [$tid]), 1, 'the confirmed call goes through'); $r2 = $run($args + ['customer_confirmed' => true]); ok(!$r2['ok'], 'and only once');
    $say('another cap'); $args2 = array_merge($args, ['items' => 'AC-503:-:2:Black']); $q = $run($args2); ok($q['ok'] && strpos($q['data']['instruction'], 'already showed') === false, 'different details get a fresh preview');
});
